/**
 * DEX838 Wire Syntax Processor
 * Format: dex(scope, @context)["subject"]
 *
 * ADR-0013 §5 changed this module's parser contract without changing the
 * grammar above: a hardcode qualifier may nest brackets, a context value may
 * contain a colon, and an optional strict mode rejects malformed input
 * instead of silently coercing it. `DEX838_REGEX` still gates the outer wire
 * shape; the two extractor regexes below stay exported for detection-only
 * use, but qualifier *extraction* now goes through the bracket-depth
 * walkers, not a global regex match. `SOFTCODE_REGEX` and `HARDCODE_REGEX`
 * carry the `/g` flag, which makes `.test()` stateful (it advances
 * `lastIndex` and can return alternating true/false across repeat calls on
 * the same string) — a caller doing detection-only `.test()` must reset
 * `lastIndex = 0` immediately before each call, as
 * `dexspine/dexcli/core/src/lib/CliPool.js` already does.
 */

export const DEX838_REGEX = /^dex\(\s*([\w-]+)\s*,\s*@([^)]+)\)\s*\["([\s\S]*)"\]$/;
export const SOFTCODE_REGEX = /dex\(([^)]*)\)/g;
export const HARDCODE_REGEX = /dex\[([^\]]*)\]/g;

/**
 * Extract every `dex[...]` qualifier from `subject`, tracking `[`/`]` depth
 * so a clause reference containing its own brackets — e.g.
 * `dex[must satisfy PCI DSS 4.0 req 6.4.3 [script inventory]]` — is captured
 * whole instead of truncating at the first `]`. Ported from the same
 * technique in packages/dexspine-tools/src/validate.js's
 * `extractWireCandidates` (ADR-0013 §5a).
 */
function extractHardcodeQualifiers(subject, { strict = false } = {}) {
  const OPEN = 'dex[';
  const results = [];
  let i = 0;
  while (i < subject.length) {
    const start = subject.indexOf(OPEN, i);
    if (start === -1) break;
    let j = start + OPEN.length;
    let depth = 1;
    while (j < subject.length && depth > 0) {
      if (subject[j] === '[') depth++;
      else if (subject[j] === ']') depth--;
      j++;
    }
    if (depth > 0) {
      if (strict) {
        throw new Error(`Unterminated dex[ hardcode qualifier in subject: ${subject}`);
      }
      // Don't abandon the whole scan over one bad qualifier — resume just
      // past this failed opening so a well-formed qualifier later in the
      // same subject is still found.
      i = start + OPEN.length;
      continue;
    }
    results.push(subject.slice(start + OPEN.length, j - 1));
    i = j;
  }
  return results;
}

/** Same idea as extractHardcodeQualifiers, over `dex(...)` softcode qualifiers. */
function extractSoftcodeQualifiers(subject, { strict = false } = {}) {
  const OPEN = 'dex(';
  const results = [];
  let i = 0;
  while (i < subject.length) {
    const start = subject.indexOf(OPEN, i);
    if (start === -1) break;
    let j = start + OPEN.length;
    let depth = 1;
    while (j < subject.length && depth > 0) {
      if (subject[j] === '(') depth++;
      else if (subject[j] === ')') depth--;
      j++;
    }
    if (depth > 0) {
      if (strict) {
        throw new Error(`Unterminated dex( softcode qualifier in subject: ${subject}`);
      }
      i = start + OPEN.length;
      continue;
    }
    results.push(subject.slice(start + OPEN.length, j - 1));
    i = j;
  }
  return results;
}

/**
 * Parse one `@context` item into a [key, value] pair. Splits on the
 * *first* `:` only, so a value may itself contain one — a URL being the
 * driving case (`target:https://www.shopify.com`). A bare flag (no `:`)
 * maps to `true`. A leading `@` on the key (a stray repeated sigil, e.g.
 * `@a:1, @b:2`) is stripped in lenient mode and rejected in strict mode
 * (ADR-0013 §5b).
 */
function parseContextItem(item, { strict = false } = {}) {
  const trimmedItem = item.trim();
  if (trimmedItem.length === 0) {
    if (strict) {
      throw new Error('Empty context item between commas');
    }
    return null;
  }

  const colonIdx = trimmedItem.indexOf(':');
  const rawKey = colonIdx === -1 ? trimmedItem : trimmedItem.slice(0, colonIdx).trim();
  const value = colonIdx === -1 ? true : trimmedItem.slice(colonIdx + 1).trim();

  const hasStraySigil = rawKey.startsWith('@');
  if (hasStraySigil && strict) {
    throw new Error(`Context key still carries a stray @ sigil: ${rawKey}`);
  }
  const key = hasStraySigil ? rawKey.slice(1).trim() : rawKey;

  if (key.length === 0) {
    if (strict) {
      throw new Error(`Empty context key in item: ${item}`);
    }
    // A malformed coordinate (`@:policy` meant to be `@layer:policy`) is
    // not a usable key/value pair — fall back to a bare flag over the
    // whole item rather than minting a nameless entry silently.
    return [trimmedItem, true];
  }

  return [key, value];
}

export function parseDEX838(wireString, { strict = false } = {}) {
  const trimmed = wireString.trim();
  const match = DEX838_REGEX.exec(trimmed);
  if (!match) {
    throw new Error(`Invalid DEX838 wire format: ${wireString}`);
  }

  const scope = match[1];
  const contextRaw = match[2];
  const subject = match[3];

  const contextMap = {};
  for (const item of contextRaw.split(',')) {
    const entry = parseContextItem(item, { strict });
    if (entry === null) continue;
    const [key, value] = entry;
    if (strict && Object.prototype.hasOwnProperty.call(contextMap, key)) {
      throw new Error(`Duplicate context key: ${key}`);
    }
    contextMap[key] = value;
  }

  const softcodeMatches = extractSoftcodeQualifiers(subject, { strict });
  const hardcodeMatches = extractHardcodeQualifiers(subject, { strict });

  return {
    scope,
    context: contextMap,
    subject,
    qualifiers: {
      softcode: softcodeMatches,
      hardcode: hardcodeMatches
    }
  };
}

export function formatDEX838(scope, contextMap, subject) {
  const contextStr = Object.entries(contextMap)
    .map(([k, v]) => (v === true ? k : `${k}:${v}`))
    .join(',');
  return `dex(${scope}, @${contextStr})["${subject}"]`;
}
